mapper.select:
SELECT * FROM soft_deleted_blobs
WHERE source_blob_store_name = #{sourceBlobStoreName}
 AND record_id > #{continuationToken}
ORDER BY record_id LIMIT #{limit};

SELECT * FROM soft_deleted_blobs
WHERE source_blob_store_name = #{sourceBlobStoreName}
  AND deleted_date < #{blobsDeletedBefore}
 AND record_id > #{continuationToken}
ORDER BY record_id LIMIT #{limit};

mapper.delete:
DELETE FROM soft_deleted_blobs
WHERE source_blob_store_name = #{sourceBlobStoreName}
LIMIT #{limit}

DELETE
FROM soft_deleted_blobs
WHERE record_id IN
(
    SELECT record_id
    FROM soft_deleted_blobs
    WHERE source_blob_store_name = #{sourceBlobStoreName}
    LIMIT #{limit}
)

mapper.select:
