WHERE source_blob_store_name = #{sourceBlobStoreName};

SELECT COUNT(*)
FROM soft_deleted_blobs
WHERE source_blob_store_name = #{sourceBlobStoreName}
  AND deleted_date < #{blobsDeletedBefore};

SELECT * FROM soft_deleted_blobs
WHERE source_blob_store_name = #{sourceBlobStoreName}
ORDER BY deleted_date ASC LIMIT 20

